drop table if exists public.kingdom_seed_staging;
create table public.kingdom_seed_staging (ord int, chunk text);
  select true, (select string_agg(chunk, '' order by ord) from public.kingdom_seed_staging)::jsonb
  on conflict (id) do update set snapshot = excluded.snapshot, updated_at = now();
  select (select string_agg(chunk, '' order by ord) from public.kingdom_seed_staging)::jsonb, 'Initial migration from static messages/*.json';
drop table public.kingdom_seed_staging;
